out = "experiments/data/_daring_work/out_blimp_04.jsonl"
with open(out, "a", encoding="utf-8") as f:
    for r in records:
        f.write(json.dumps(r, ensure_ascii=False) + "\n")
print(f"appended {len(records)} records (lines 89-111)")
